mapper.insert:
insert into hr_welfare_points (
    staff_id, points_type, points_value, points_source, source_id, source_desc,
    expire_date, used_points, available_points, transaction_type, transaction_time, operator, remark, status
) values (
             #{staff_id}, #{points_type}, #{points_value}, #{points_source}, #{source_id}, #{source_desc},
             #{expire_date}, #{used_points}, #{available_points}, #{transaction_type}, 
             COALESCE(#{transaction_time}, NOW()), #{operator}, #{remark}, #{status}
         )

mapper.update:
update hr_welfare_points
points_type = #{points_type}, points_value = #{points_value}, points_source = #{points_source}, source_desc = #{source_desc}, expire_date = #{expire_date}, used_points = #{used_points}, available_points = #{available_points}, transaction_type = #{transaction_type}, operator = #{operator}, remark = #{remark},
where id = #{id}

mapper.select:
select wp.id, wp.staff_id, wp.points_type, wp.points_value, wp.points_source, wp.source_id, wp.source_desc, wp.rule_id, wp.auto_generated, wp.expire_date, wp.used_points, wp.available_points, wp.transaction_type, wp.transaction_time, wp.operator, wp.remark, wp.status, s.sname, s.sid, DATE_FORMAT(wp.expire_date,'%Y-%m-%d') as expire_date1, DATE_FORMAT(wp.transaction_time,'%Y-%m-%d %H:%i:%s') as transaction_time1, COALESCE(( SELECT COALESCE( SUM(CASE WHEN wp2.transaction_type = 'EARN' AND wp2.status = 1 THEN wp2.points_value ELSE 0 END) - SUM(CASE WHEN wp2.transaction_type = 'USE' AND wp2.status = 1 THEN COALESCE(wp2.used_points, wp2.points_value, 0) ELSE 0 END), 0 ) FROM hr_welfare_points wp2 WHERE wp2.staff_id = wp.staff_id AND wp2.status = 1 ), 0) as current_available from hr_welfare_points wp left join hr_employee s on wp.staff_id = s.id where wp.status = 1
and wp.staff_id = #{staff_id}
and wp.points_type = #{points_type}
and wp.transaction_type = #{transaction_type}
and s.sname like concat('%',#{sname},'%')
order by wp.transaction_time desc limit #{startIndex}, #{pageSize}

mapper.update:
update hr_welfare_points
set status = 0
where id = #{id}

mapper.select:
select count(*)
from hr_welfare_points wp
left join hr_employee s on wp.staff_id = s.id
where wp.status = 1

    and wp.staff_id = #{staff_id}


    and wp.points_type = #{points_type}


    and wp.transaction_type = #{transaction_type}


    and s.sname like concat('%',#{sname},'%')

SELECT s.id as staff_id, s.sname as staff_name, s.depart_id, d.dname as depart_name, COALESCE(SUM(CASE WHEN wp.transaction_type = 'EARN' AND wp.status = 1 THEN wp.points_value ELSE 0 END), 0) as total_earned, COALESCE(SUM(CASE WHEN wp.transaction_type = 'USE' AND wp.status = 1 THEN COALESCE(wp.used_points, wp.points_value, 0) ELSE 0 END), 0) as total_used, COALESCE(SUM(CASE WHEN wp.transaction_type = 'EARN' AND wp.status = 1 THEN wp.points_value ELSE 0 END) - SUM(CASE WHEN wp.transaction_type = 'USE' AND wp.status = 1 THEN COALESCE(wp.used_points, wp.points_value, 0) ELSE 0 END), 0) as current_balance, MAX(CASE WHEN wp.status = 1 THEN wp.transaction_time END) as last_earn_time FROM hr_employee s LEFT JOIN sys_department d ON s.depart_id = d.id LEFT JOIN hr_welfare_points wp ON s.id = wp.staff_id
AND wp.transaction_time >= #{startDate}
WHERE 1=1
AND s.depart_id = #{departId}
GROUP BY s.id, s.sname, s.depart_id, d.dname HAVING total_earned > 0 ORDER BY current_balance DESC, total_earned DESC
LIMIT #{limit}
